$$[{"id": "fl-1", "nome": "Boas-vindas e apresentação", "ativo": true, "passos": [{"id": "p-1", "canal": "WhatsApp", "diasApos": 0, "mensagem": "Olá, {nome}! Aqui é a Ana, da {empresa_nome}. Vi que você pode se interessar por nossos serviços. Posso te enviar uma apresentação rápida?"}, {"id": "p-2", "canal": "E-mail", "diasApos": 1, "mensagem": "Oi {nome}, conforme conversamos, segue nossa apresentação institucional com cases e diferenciais. Fico à disposição para tirar qualquer dúvida!\n\n{assinatura}"}, {"id": "p-3", "canal": "WhatsApp", "diasApos": 3, "mensagem": "Oi {nome}, tudo bem? Vi que você ainda não teve tempo de ver a apresentação. Quer que eu resuma os principais pontos por aqui?"}], "gatilho": "novo_lead", "descricao": "Sequência de primeiro contato para leads recém-ativados no Kanban."}, {"id": "fl-2", "nome": "Follow-up pós-orçamento", "ativo": true, "passos": [{"id": "p-1", "canal": "WhatsApp", "diasApos": 1, "mensagem": "Oi {nome}, te enviei o orçamento ontem. Conseguiu dar uma olhada? Posso esclarecer qualquer ponto."}, {"id": "p-2", "canal": "E-mail", "diasApos": 3, "mensagem": "Olá {nome}, reforçando o envio do orçamento. A validade é de {validade}. Se precisar de alguma condição especial, me avise!\n\n{assinatura}"}, {"id": "p-3", "canal": "WhatsApp", "diasApos": 7, "mensagem": "{nome}, o orçamento expira em breve. Quer que eu reserve um horário pra gente fechar os detalhes?"}], "gatilho": "orcamento_enviado", "descricao": "Cadência de 1/3/7 dias após o envio do orçamento, para não deixar a proposta esfriar."}, {"id": "fl-3", "nome": "Reativação de lead inativo", "ativo": false, "passos": [{"id": "p-1", "canal": "E-mail", "diasApos": 0, "mensagem": "Oi {nome}, faz um tempo que não conversamos. Queria saber se o seu interesse em {oferta} continua de pé. Posso ajudar em algo?\n\n{assinatura}"}, {"id": "p-2", "canal": "WhatsApp", "diasApos": 2, "mensagem": "Oi {nome}, passei por aqui e lembrei de você! Ainda faz sentido a gente conversar sobre {oferta}? Se preferir, sigo sem te incomodar."}], "gatilho": "lead_inativo", "descricao": "Tentativa de reengajar leads que pararam de responder ou ficaram parados no funil."}, {"id": "fl-4", "nome": "Aniversário de parceria", "ativo": false, "passos": [{"id": "p-1", "canal": "WhatsApp", "diasApos": 0, "mensagem": "{nome}, parabéns pelo seu dia! Foi um prazer trabalhar com a {empresa}. Que venham mais conquistas juntos!"}], "gatilho": "aniversario", "descricao": "Mensagem de relacionamento no aniversário do lead ou da parceria."}]$$::jsonb);

